        // ‖A's stored block k‖_F.
        static float BlockFrobenius(in floatBSR A, int k)
        {
            int blockLen = A.BR * A.BC;
            int off = k * blockLen;
            float s = 0;
            for (int t = 0; t < blockLen; t++)
