            for (int i = 0; i < nb; i++) aggId[i] = -1;
            numAgg = 0;

            // ---- pass 1: root aggregates ----
            for (int i = 0; i < nb; i++)
            {
                if (aggId[i] != -1) continue;

                int s = A.RowPtr[i], e = A.RowPtr[i + 1];

