            for (int i = 0; i < nb; i++) inP1[i] = aggId[i] != -1;

            // ---- pass 2: attach leftovers to the strongest pass-1 aggregate ----
            for (int i = 0; i < nb; i++)
            {
                if (aggId[i] != -1) continue;

                int s = A.RowPtr[i], e = A.RowPtr[i + 1];
                int bestAgg = -1;
                float bestStr = -1;
                for (int k = s; k < e; k++)
